export function restoreTicketDocumentsProgressiveLoading(path, source) {
  if (path.endsWith("/DocumentsSection.tsx")) return restoreDocumentProgressiveLoading(source);
  if (path.endsWith("/TicketDetailDrawer.tsx")) return restoreTicketDetailProgressiveLoading(source);
  const name = path.split("/").at(-1).replace(/\.tsx$/, "");
  return initialPresentationChanges[name] ? restoreTicketDocumentInitialPresentation(source, name) : source;
}

